[{"order":1,"type":"heading","text":"Rendering Dynamic Views and Passing Data in Express.js"},{"order":2,"type":"paragraph","text":"Express.js provides robust support for template engines to render dynamic HTML pages. Instead of serving static files, template engines allow you to inject data directly from your backend into your views, creating responsive web applications."},{"order":3,"type":"subheading","text":"Step 1: Setting up EJS Template Engine"},{"order":4,"type":"paragraph","text":"First, you need to install a template engine. EJS (Embedded JavaScript) is one of the most popular choices for Express. Install it via npm using your terminal."},{"order":5,"type":"code","text":"npm install ejs"},{"order":6,"type":"paragraph","text":"Next, configure Express to use EJS as the view engine in your main application file (usually app.js or server.js)."},{"order":7,"type":"code","text":"const express = require('express');
const app = express();

// Set EJS as the view engine
app.set('view engine', 'ejs');

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});"},{"order":8,"type":"subheading","text":"Step 2: Creating the Views Directory"},{"order":9,"type":"paragraph","text":"By default, Express looks for view templates inside a folder named 'views' in the root directory of your project. Create a folder named 'views' and add a file called 'index.ejs' inside it."},{"order":10,"type":"code","text":"<!DOCTYPE html>
<html>
<head>
  <title><%= title %></title>
</head>
<body>
  <h1><%= message %></h1>
  <ul>
    <% items.forEach(function(item) { %>
      <li><%= item %></li>
    <% }); %>
  </ul>
</body>
</html>"},{"order":11,"type":"subheading","text":"Step 3: Passing Data from Routes"},{"order":12,"type":"paragraph","text":"Use the res.render() function to render your view and pass an object containing the data you want to display. The keys of this object will become variables accessible inside your EJS template."},{"order":13,"type":"code","text":"app.get('/', (req, res) => {
  const viewData = {
    title: 'Home Page',
    message: 'Welcome to Express.js Dynamic Views!',
    items: ['Apple', 'Banana', 'Orange']
  };

  res.render('index', viewData);
});"},{"order":14,"type":"subheading","text":"Summary of Best Practices"},{"order":15,"type":"bullet_point","text":"Always organize your template files inside a dedicated 'views' folder."},{"order":16,"type":"bullet_point","text":"Use res.render() instead of res.sendFile() when dealing with dynamic data."},{"order":17,"type":"bullet_point","text":"Sanitize and validate data on the backend before passing it to views to prevent XSS attacks."}]
